نقش سازمانی: retail_logistics_manager (retail_logistics_manager)

درخواست کاربر:
«مسیر مرکز الف» دیر می‌رسد؛ ریشه را پیدا کن. (مدیر توزیع — زنجیرهٔ افق کوروش)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "delivery_routes",
      "description": "عملکرد مسیرهای توزیع هفتگی",
      "dimensions": [
        "route",
        "week"
      ],
      "measures": [
        "deliveries",
        "on_time_pct",
        "cost_m"
      ]
    },
    {
      "dataset": "dock_log",
      "description": "صف بارگیری مرکز توزیع",
      "dimensions": [
        "day"
      ],
      "measures": [
        "avg_queue_hours",
        "docked_trucks"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "on_time_delivery",
      "description": "تحویل به‌موقع",
      "formula": "تحویل‌های به‌موقع تقسیم بر کل",
      "unit": "درصد",
      "dimensions": [
        "route"
      ]
    },
    {
      "metric": "dock_dwell",
      "description": "توقف وانت در بارگیری",
      "formula": "میانگین ساعت صف تا تخلیه",
      "unit": "ساعت",
      "dimensions": [
        "day"
      ]
    }
  ],
  "business_context": [
    "مرکز توزیع واحد و ۲۶ مسیر توزیع برای ۱۲۰ شعبه",
    "پنجرهٔ تحویل توافقی با شعبه‌ها دو ساعت",
    "اسلات‌بندی بارگیری از ساعت ۵ صبح آغاز می‌شود"
  ]
}

TOOL_CALL:
{
  "tool": "compare_periods",
  "arguments": {
    "metrics": [
      "on_time_delivery"
    ],
    "period_a": "prev_week",
    "period_b": "curr_week"
  }
}

TOOL_OBSERVATION:
{
  "route": "مسیر مرکز الف",
  "on_time_pct": {
    "prev": 91.6,
    "curr": 77.1,
    "change_pp": -14.5
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "dock_log",
    "filters": {
      "period": [
        "prev_week",
        "curr_week"
      ]
    }
  }
}

TOOL_OBSERVATION:
{
  "avg_queue_hours": {
    "prev": 1.0,
    "curr": 3.1,
    "change_h": 2.1
  },
  "trucks_before_slot": "65٪ وانت‌ها بدون اسلات آمده‌اند"
}

نقش سازمانی: retail_logistics_manager (retail_logistics_manager)

درخواست کاربر:
آیا ناوگان بیرونی برای پیک ببندیم؟ (هایپرمی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "delivery_routes",
      "description": "عملکرد مسیرهای توزیع هفتگی",
      "dimensions": [
        "route",
        "week"
      ],
      "measures": [
        "deliveries",
        "on_time_pct",
        "cost_m"
      ]
    },
    {
      "dataset": "fleet_utilization",
      "description": "اشغال و مصرف ناوگان",
      "dimensions": [
        "vehicle_class",
        "week"
      ],
      "measures": [
        "load_pct",
        "fuel_liters",
        "trips"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "fleet_utilization",
      "description": "اشغال ناوگان",
      "formula": "بار مفید تقسیم بر ظرفیت",
      "unit": "درصد",
      "dimensions": [
        "vehicle_class"
      ]
    }
  ],
  "business_context": [
    "مرکز توزیع واحد و ۲۶ مسیر توزیع برای ۱۲۰ شعبه",
    "زنجیرهٔ سرد برای لبنیات و سرمودی الزامی است",
    "اسلات‌بندی بارگیری از ساعت ۵ صبح آغاز می‌شود"
  ]
}

